package com.aetherforge.api;import com.aetherforge.repo.FactoryRepository;import com.aetherforge.repo.MachineRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class FactoryController {private final FactoryRepository f;private final MachineRepository m;public FactoryController(FactoryRepository f,MachineRepository m){this.f=f;this.m=m;}@GetMapping("/factories") List<Map<String,Object>> factories(){return f.factories();}@GetMapping("/factories/{id}/summary") Map<String,Object> summary(@PathVariable String id){return f.summary(id);}@GetMapping("/dashboard/summary") Map<String,Object> dashboard(){return Map.of("factory",f.summary("00000000-0000-0000-0000-000000000001"),"machines",m.metrics());}}
